import{_ as r,a0 as i,w as p,s as a,ao as s,I as e,x as u,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"如何在 Ubuntu 桌面中应用强调色 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 桌面中应用强调色 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 桌面中应用强调色 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 桌面中应用强调色 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220814 How to Apply Accent Colour in Ubuntu Desktop","title":"如何在 Ubuntu 桌面中应用强调色","tag":"202209","desc":""},"relativePath":"202209/20220814 How to Apply Accent Colour in Ubuntu Desktop.md","filePath":"[post].md"}'),b={name:"202209/20220814 How to Apply Accent Colour in Ubuntu Desktop.md"};function d(m,t,T,C,g,w){const l=i("Link");return p(),a("div",null,[t[15]||(t[15]=s('<h1 id="如何在-ubuntu-桌面中应用强调色" tabindex="-1">如何在 Ubuntu 桌面中应用强调色 <a class="header-anchor" href="#如何在-ubuntu-桌面中应用强调色" aria-label="Permalink to “如何在 Ubuntu 桌面中应用强调色”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/13/075753yoi4j2ozozkkxmmk.jpg" alt=""></p><blockquote><p>得益于开发者们最近的贡献，在 Ubuntu 中使用自己的强调色是很简单的。</p></blockquote><p>每个 Linux 发行版都有它们默认的主题，具有各自的主色调。强调色用于在各个设置中突出主色调。通常，主色调和强调色应该形成对比和补充。</p><p>在最近的 GNOME 桌面的更新之后，Ubuntu 桌面在 22.04 LTS 版本中引入了强调色。</p><p>尽管如何应用它们是显而易见的，但是为了 Linux 的新手，我将解释如何在 Ubuntu 桌面中使用强调色。</p><h3 id="在-ubuntu-桌面中应用强调色" tabindex="-1">在 Ubuntu 桌面中应用强调色 <a class="header-anchor" href="#在-ubuntu-桌面中应用强调色" aria-label="Permalink to “在 Ubuntu 桌面中应用强调色”">​</a></h3><ol><li>从应用菜单中打开 <ruby>系统设置<rt>System Settings</rt></ruby></li><li>进入 <ruby>外观<rt>Appearance</rt></ruby> 菜单</li><li>在 <ruby>风格<rt>Style</rt></ruby> 菜单下，你应该见到一套预设的颜色。</li><li>选择其中的一个来改变强调色。</li></ol><p>一旦更改，强调色将被应用到 GTK 应用程序中的选区和 GTK 控件中，如切换按钮和文件夹的默认外观。</p><p>默认的强调色是橙色，有十种颜色可供选择，具体如下：</p><ul><li>橙色</li><li>树皮色</li><li>鼠尾草色</li><li>橄榄绿</li><li>铬绿</li><li>普鲁士绿</li><li>蓝色</li><li>紫色</li><li>品红色</li><li>红色</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/08/Accent-Colour-in-Ubuntu.jpg" alt="Accent Colour in Ubuntu"></p><p>（LCTT 译注：树皮色是一种棕色，鼠尾草色是一种灰绿色。）</p><p>你应该记住一点，深色和浅色的主题的强调色组合可能改变你的桌面的整体外观。</p><p>以上的特性只是只适用于目前使用 GNOME 桌面的 Ubuntu，而不适用于其它提供原生 GNOME 的发行版，例如 Fedora Workstation。因为有一些内容是由 Ubuntu 团队开发的，并且并没有合并到 GNOME 上游。</p><h3 id="kubuntu-中的强调色" tabindex="-1">Kubuntu 中的强调色 <a class="header-anchor" href="#kubuntu-中的强调色" aria-label="Permalink to “Kubuntu 中的强调色”">​</a></h3><p>使用带有 KDE Plasma 桌面的 Kubuntu，你可以简单地使用强调色。KDE Plasma 提供了预设的颜色，也有自定义的颜色选择器选项。另外，自 KDE Plasma 5.25 起，强调色可以根据壁纸来改变。</p><p>为了在 Kubuntu 中改变它，跟着下面的步骤走：</p><ul><li>在应用菜单中打开 <ruby>系统设置<rt>System Settings</rt></ruby></li><li>进入 <ruby>外观<rt>Appearance</rt></ruby> &gt; <ruby>全局主题<rt>Global Theme</rt></ruby> &gt; <ruby>颜色<rt>Colours</rt></ruby> 标签</li><li>选择你的强调色</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/05/KDE-Plasma-5.25-Accent-Colour-Change-Based-on-wallpaper-1024x611.jpg" alt="KDE Plasma 5.25 - Accent Colour Change Based on wallpaper"></p><p>我知道 Lubuntu 与 Xubuntu 并没有这个特性。而且它不太可能很快到来。</p><p>使用愉快。</p><hr>',23)),e("p",null,[t[1]||(t[1]=u("via: ",-1)),n(l,{href:"https://www.debugpoint.com/ubuntu-accent-colour/"},{default:o(()=>[...t[0]||(t[0]=[u("https://www.debugpoint.com/ubuntu-accent-colour/",-1)])]),_:1})]),e("p",null,[t[6]||(t[6]=u("作者：",-1)),n(l,{href:"https://www.debugpoint.com/author/admin1/"},{default:o(()=>[...t[2]||(t[2]=[u("Arindam",-1)])]),_:1}),t[7]||(t[7]=u(" 选题：",-1)),n(l,{href:"https://github.com/lkxed"},{default:o(()=>[...t[3]||(t[3]=[u("lkxed",-1)])]),_:1}),t[8]||(t[8]=u(" 译者：",-1)),n(l,{href:"https://github.com/yjacks"},{default:o(()=>[...t[4]||(t[4]=[u("yjacks",-1)])]),_:1}),t[9]||(t[9]=u(" 校对：",-1)),n(l,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[u("wxy",-1)])]),_:1})]),e("p",null,[t[12]||(t[12]=u("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[u("LCTT",-1)])]),_:1}),t[13]||(t[13]=u(" 原创编译，",-1)),n(l,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[u("Linux中国",-1)])]),_:1}),t[14]||(t[14]=u(" 荣誉推出",-1))])])}const x=r(b,[["render",d]]);export{k as __pageData,x as default};
